#include <memory>
#include <cassert>
#include <type_traits>
#include <utility>
struct Object : std::enable_shared_from_this<Object> {};
int main() {
    auto object = std::make_shared<Object>();
    assert(object->weak_from_this().lock() == object);
    std::weak_ptr<Object> observer = object;
    object.reset();
    assert(observer.expired());
}
